  \href{https://doi.org/10.1063/1.1704727}{doi:10.1063/1.1704727}.

  \item[\textup{[LS04]}]\label{ref:p34-lieb-seiringer}
  E. H. Lieb and R. Seiringer, ``Equivalent Forms of the
  Bessis--Moussa--Villani Conjecture,'' \emph{Journal of Statistical Physics}
